public class Job {

    // Information generated by the system
    private int jobId;
    private String studentId;

    // Information entered by the student
    private String title;
    private String applicationName;
    private String description;
    private String taskSize;

    // Calculated by the system
    private int workloadUnits;
    private int estimatedDuration;

    // Job execution information
    private String submissionTime;
    private String status;
    private int assignedGpuId;
    private String startTime;
    private String finishTime;

    // Cancellation information
    private String cancellationTime;
    private String cancelledBy;
    private String cancellationReason;

    // Payment information
    private int chargedMinutes;
    private boolean settled;

    public Job(int jobId, String studentId, String title, String applicationName, String description, String taskSize, String submissionTime) {

        this.jobId = jobId;
        this.studentId = studentId;
        this.title = title;
        this.applicationName = applicationName;
        this.description = description;
        this.submissionTime = submissionTime;

        setTaskSize(taskSize);

        // Initial values for a new job
        status = "Queued";
        assignedGpuId = -1;

        startTime = null;
        finishTime = null;

        cancellationTime = null;
        cancelledBy = null;
        cancellationReason = null;

        chargedMinutes = 0;
        settled = false;
    }

    private void setTaskSize(String taskSize) {

        this.taskSize = taskSize;

        if (taskSize.equalsIgnoreCase("Small")) {
            workloadUnits = 5;
            estimatedDuration = 5;
        }
        else if (taskSize.equalsIgnoreCase("Medium")) {
            workloadUnits = 15;
            estimatedDuration = 15;
        }
        else if (taskSize.equalsIgnoreCase("Large")) {
            workloadUnits = 30;
            estimatedDuration = 30;
        }
        else if (taskSize.equalsIgnoreCase("Very large")) {
            workloadUnits = 60;
            estimatedDuration = 60;
        }
        else {
            System.out.println("Invalid task size");
            workloadUnits = 0;
            estimatedDuration = 0;
        }
    }

    public int getJobId() {
        return jobId;
    }

    public String getStudentId() {
        return studentId;
    }

    public String getTitle() {
        return title;
    }

    public String getApplicationName() {
        return applicationName;
    }

    public String getDescription() {
        return description;
    }

    public String getTaskSize() {
        return taskSize;
    }

    public int getWorkloadUnits() {
        return workloadUnits;
    }

    public int getEstimatedDuration() {
        return estimatedDuration;
    }

    public String getSubmissionTime() {
        return submissionTime;
    }

    public String getStatus() {
        return status;
    }

    public int getAssignedGpuId() {
        return assignedGpuId;
    }

    public String getStartTime() {
        return startTime;
    }

    public String getFinishTime() {
        return finishTime;
    }

    public String getCancellationTime() {
        return cancellationTime;
    }

    public String getCancelledBy() {
        return cancelledBy;
    }

    public String getCancellationReason() {
        return cancellationReason;
    }

    public int getChargedMinutes() {
        return chargedMinutes;
    }

    public boolean isSettled() {
        return settled;
    }

    public boolean startJob(int gpuId, String startTime) {

        if (status.equals("Queued")) {
            status = "Running";
            assignedGpuId = gpuId;
            this.startTime = startTime;

            return true;
        }

        return false;
    }

    public boolean completeJob(String finishTime) {

        if (status.equals("Running")) {
            status = "Completed";
            this.finishTime = finishTime;

            return true;
        }

        return false;
    }

    public boolean cancelJob(String cancellationTime, String cancelledBy, String cancellationReason) {

        if (status.equals("Queued") || status.equals("Running")) {

            if (status.equals("Running")) {
                finishTime = cancellationTime;
            }

            status = "Cancelled";

            this.cancellationTime = cancellationTime;
            this.cancelledBy = cancelledBy;
            this.cancellationReason = cancellationReason;

            return true;
        }

        return false;
    }

    public void settleJob(int chargedMinutes) {

        if (!settled) {
            this.chargedMinutes = chargedMinutes;
            settled = true;
        }
    }

    public String toString() {

        String gpu;

        if (assignedGpuId == -1) {
            gpu = "Not assigned";
        }
        else {
            gpu = "" + assignedGpuId;
        }

        return "Job ID: " + jobId
                + ", Student ID: " + studentId
                + ", Title: " + title
                + ", Application: " + applicationName
                + ", Size: " + taskSize
                + ", Duration: " + estimatedDuration
                + ", Status: " + status
                + ", GPU: " + gpu;
    }
}